import{_ as r,o as t,c as a,a0 as e}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/start.md","filePath":"guide/start.md"}'),l={name:"guide/start.md"};function n(s,o,i,d,g,c){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>欢迎使用 <strong>KernelEX</strong>！本章节将带你快速了解环境要求、安装授权流程以及如何执行你的第一个脚本。</p><hr><h2 id="📱-运行环境要求" tabindex="-1">📱 运行环境要求 <a class="header-anchor" href="#📱-运行环境要求" aria-label="Permalink to &quot;📱 运行环境要求&quot;">​</a></h2><p>在开始使用前，请确保你的 Android 设备满足以下条件：</p><ul><li><strong>操作系统</strong>：Android 8.0 (API 26) 及以上</li><li><strong>设备架构</strong>：<code>arm64-v8a</code>、<code>armeabi-v7a</code>、<code>x86_64</code></li><li><strong>ROOT 方案</strong>：已安装并激活 <strong>Magisk</strong>、<strong>KernelSU</strong> 或 <strong>APatch</strong> 超级用户管理器</li><li><strong>存储权限</strong>：Android 11+ 设备需授予「管理所有文件」权限（用于读取/导入外部存储脚本）</li></ul><hr><h2 id="🔑-权限配置指引" tabindex="-1">🔑 权限配置指引 <a class="header-anchor" href="#🔑-权限配置指引" aria-label="Permalink to &quot;🔑 权限配置指引&quot;">​</a></h2><p>首次打开 KernelEX 时，应用将进入**权限检查门（Permission Gate）**引导界面：</p><ol><li><strong>ROOT 超级用户权限</strong>：点击「请求 ROOT 授权」，在弹出的授权管理器（Magisk/KernelSU/APatch）中点击「永久允许」。</li><li><strong>所有文件访问权限</strong>：点击前往系统设置，开启「授予所有文件管理权限」，以便应用读取外部存储中的脚本。</li><li><strong>忽略电池优化（推荐开启）</strong>：点击申请加入系统电池白名单，防止后台长时间执行繁重脚本时被系统进程查杀。</li></ol><div class="tip custom-block"><p class="custom-block-title">自动感知</p><p>所有必要权限就绪后，页面将自动感知并进入软件主界面，无需反复手动刷新。</p></div><hr><h2 id="🚀-执行你的第一个脚本" tabindex="-1">🚀 执行你的第一个脚本 <a class="header-anchor" href="#🚀-执行你的第一个脚本" aria-label="Permalink to &quot;🚀 执行你的第一个脚本&quot;">​</a></h2><p>KernelEX 提供多种便捷的文件执行方式：</p><h3 id="方式-1-主页路径输入与选择" tabindex="-1">方式 1：主页路径输入与选择 <a class="header-anchor" href="#方式-1-主页路径输入与选择" aria-label="Permalink to &quot;方式 1：主页路径输入与选择&quot;">​</a></h3><ol><li>打开应用，进入底栏「<strong>主页</strong>」；</li><li>在输入框直接输入脚本绝对路径，或点击「<strong>从文件管理器选择</strong>」挑选 <code>.sh</code> 或 <code>.so</code> 文件；</li><li>点击「<strong>立即执行</strong>」，应用将自动跳转到「<strong>终端</strong>」页面并实时打印输出。</li></ol><h3 id="方式-2-工作区目录一键执行" tabindex="-1">方式 2：工作区目录一键执行 <a class="header-anchor" href="#方式-2-工作区目录一键执行" aria-label="Permalink to &quot;方式 2：工作区目录一键执行&quot;">​</a></h3><ol><li>将你的脚本或可执行文件放入默认工作区目录：<code>/data/adb/KernelEX/</code>；</li><li>在「主页」下方卡片中点击对应文件即可直接选定或启动。</li></ol><h3 id="方式-3-全盘文件管理器长按添加" tabindex="-1">方式 3：全盘文件管理器长按添加 <a class="header-anchor" href="#方式-3-全盘文件管理器长按添加" aria-label="Permalink to &quot;方式 3：全盘文件管理器长按添加&quot;">​</a></h3><ol><li>切换至底栏「<strong>文件</strong>」页面；</li><li>浏览至脚本所在目录，长按目标文件呼出操作菜单；</li><li>选择「<strong>添加到 KernelEX</strong>」，文件将自动复制到工作区并自动设置 <code>chmod 777</code> 权限（若在设置中开启了「添加后自动执行」，将立即开始运行）。</li></ol><hr><h2 id="💻-终端操作与控制" tabindex="-1">💻 终端操作与控制 <a class="header-anchor" href="#💻-终端操作与控制" aria-label="Permalink to &quot;💻 终端操作与控制&quot;">​</a></h2><p>进入「<strong>终端</strong>」页面后，你可以进行以下操作：</p><ul><li><strong>发送标准输入（stdin）</strong>：如果脚本在等待用户交互输入（例如 <code>read -p &quot;请输入: &quot;</code>），在底部输入框输入内容并点击「发送」或回车即可。</li><li><strong>发送中断信号（Ctrl+C）</strong>：点击「<strong>中断</strong>」按钮向当前运行中的子进程发送 <code>SIGINT</code>（<code>kill -2</code>）信号。</li><li><strong>强制结束任务</strong>：点击「<strong>结束进程</strong>」按钮强行终止任务（<code>kill -9</code>）。</li><li><strong>复制输出</strong>：点击顶部「<strong>复制输出</strong>」一键复制控制台纯文本日志到剪贴板。</li><li><strong>清屏与重跑</strong>：任务结束后点击「<strong>清屏</strong>」重置控制台，或点击「<strong>重新运行</strong>」再次执行上次任务。</li></ul>',24)])])}const p=r(l,[["render",n]]);export{u as __pageData,p as default};
